#!/usr/bin/env node
'use strict';

/**
 * Angular's builder has no `?raw` import (Vite gives Vue one, and the Next demo
 * reads its source in a Server Component). So the sources are embedded into a
 * generated module instead.
 *
 * Wired to `prestart` and `prebuild`, so the panel can never show stale code:
 * whatever is on disk at build time is what gets shipped.
 */

const fs = require('fs');
const path = require('path');

const APP_DIR = path.resolve(__dirname, '..', 'src', 'app');
const DEMOS = ['enterprise', 'wizard'];
const OUT = path.join(APP_DIR, 'demo-sources.ts');

const entries = DEMOS.map((name) => {
  const file = path.join(APP_DIR, 'demos', `${name}.component.ts`);
  const source = fs.readFileSync(file, 'utf8');
  return `  ${name}: ${JSON.stringify(source)},`;
}).join('\n');

const output = `// GENERATED by scripts/embed-demo-sources.js - do not edit by hand.
// Regenerated on every \`npm start\` and \`npm run build\`.
export const DEMO_SOURCES: Record<string, string> = {
${entries}
};
`;

fs.writeFileSync(OUT, output, 'utf8');
process.stdout.write(
  `embed-demo-sources: wrote ${path.relative(process.cwd(), OUT)} (${DEMOS.join(
    ', '
  )})\n`
);
